import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第一卷 蝉鸣 · 第10章_开学","description":"","frontmatter":{},"headers":[],"relativePath":"第10章_开学.md","filePath":"第10章_开学.md"}'),r={name:"第10章_开学.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第一卷-蝉鸣-·-第10章-开学" tabindex="-1">第一卷 蝉鸣 · 第10章_开学 <a class="header-anchor" href="#第一卷-蝉鸣-·-第10章-开学" aria-label="Permalink to &quot;第一卷 蝉鸣 · 第10章_开学&quot;">​</a></h1><p>行李箱合不上的那天清早，我就知道这个秋天和以前不一样了。</p><p>衣服叠了又压，压了又弹起来。被角顶着箱盖，怎么都扣不上。我坐在箱子上，听见拉链轻轻响了一声，屋里有股旧木头和肥皂混在一起的味道。窗外蝉还在叫，叫得薄，像最后一层纱。</p><p>妈妈在门口说，带少一点，缺什么以后再送。我点头，手上还在把那件洗得发白的外套往边上塞。</p><p>其实我真正想带的东西很小，小到一只手就能握住。</p><p>抽屉最里面有一张纸条，边角已经软了。上面是我初三夏天写的字，墨有点化。那天枇杷很黄，汁水沾到指尖，纸上也留下一点淡淡的甜香。我把纸条拿出来，看了很久，又折好，放进贴身的袋子里。</p><p>除了这张纸，还有一颗纸星星。五个角，被捏得有点扁，放在掌心几乎没有分量。那是她留下的，我一直没舍得扔。</p><p>开学前最后一次回南雾中学，是去拿剩下的书。</p><p>校门口的树影还是老样子，风一吹，叶子哗哗响。传达室的广播放着音乐，声音远远的，听不清词。空气里有粉笔灰和雨后青苔的味道，操场上有人在跑步，鞋底擦过地面，沙沙的。</p><p>我在走廊上看见了江苒。</p><p>她背着一个鼓鼓的包，钥匙挂在包侧，上面坠着一只小铃铛。走一步，铃铛就轻轻响一下，清脆得很。她走得很快，发梢被风吹起来，又落回去。</p><p>“沈聿。”她先叫我。</p><p>我停下来，心跳快了一拍，又慢慢压下去。</p><p>“你来拿书？”她问。</p><p>“嗯。”我说，“你呢。”</p><p>“我也来拿书。”她笑了一下，眼睛弯起来，“顺便看看教室。”</p><p>我们一起往楼上走。楼梯间很窄，脚步声叠在一起。她的铃铛一直在响，叮叮的，像在数台阶。</p><p>教室门开着，里面空荡荡的。桌椅堆在后面，黑板上还有没擦干净的字，粉笔印子白白的。风从窗户进来，窗帘轻轻飘，带进来外面桂花的香，甜丝丝的。</p><p>她走到原来坐的位置旁，伸手摸了一下桌面。</p><p>“这里有一道划痕，你还记得吗。”她说。</p><p>“记得。”我说，“你用笔画的。”</p><p>“才没有。”她回头看我，嘴角翘着，“明明是你刻的。”</p><p>我没争，低头笑了笑。指尖碰到桌面，木头凉凉的，有点粗糙。</p><p>沉默了一会儿，她把包放下来，从里面掏出一瓶橘子汽水，放在桌上。</p><p>“给你。”她说。</p><p>瓶身冰凉，上面挂着水珠。我接过来，握在手里，水珠沾到掌心，凉意一下渗进来。</p><p>“你去市三中，远吗。”她问。</p><p>“坐车要一段时间。”我说，“听说校园很大。”</p><p>“那很好啊。”她点点头，声音很轻，“大校园，新的同学。”</p><p>她说这话的时候，手指一直在拨那只小铃铛。铃铛转来转去，发出细碎的响。她的目光落在窗外，落在很远的云上。</p><p>我拧开汽水，喝了一口。气泡在舌尖炸开，酸甜的味道冲上来，有点呛。我把瓶子递给她，她摆摆手。</p><p>“你喝。”她说，“我不渴。”</p><p>风又吹进来，带着热气。蝉声从远处传来，一阵一阵的。我忽然觉得喉咙有点紧，想说点什么，又不知道说什么。</p><p>临走时，顾远在楼下喊我们。</p><p>他抱着一摞书，跑得满头是汗，脸上红红的。</p><p>“你们俩真不够意思。”他喘着气说，“拿书也不叫我。”</p><p>江苒笑出声：“你早说过你早就拿完了呀。”</p><p>“我是拿完了。”顾远把书往上一托，“我是来送你们的，顺便看看热闹。”</p><p>他看看我，又看看江苒，忽然压低声音。</p><p>“听说分开之后，课程就不一样了。”他说，“一个往文，一个往理，时间都对不上。”</p><p>没人接话。铃铛轻轻响了一声，又停了。</p><p>林小满从小卖部那边跑过来，手里拿着两根冰棍，递给我们。她跑得急，鞋带散了也不知道。</p><p>“一人一根。”她说，“开学顺利。”</p><p>冰棍很甜，薄荷味的，含在嘴里凉凉的，一直凉到心里。我咬了一口，听见冰碎裂的声音，细细的。</p><p>何晓站在远处朝我们挥手，手里举着相机，说要留个影。我们几个站在一起，背后是旧教学楼，墙皮剥落的地方露出灰色。快门响的时候，江苒的铃铛正好被风吹动，响了一下。</p><p>拍完，何晓跑过来给我们看。照片里，我们都在笑，只有风把头发吹得有点乱。</p><p>叶老师正好从办公室出来，怀里抱着作业本。她看见我们，停下来。</p><p>“都来了。”她说，语气温和，“以后在新学校，也要好好吃饭，好好睡觉。”</p><p>我们点头。她的目光在我和江苒身上多停了一会儿，又移开，什么也没多说。</p><p>回家的路上，我和江苒顺路走了一段。</p><p>石板路被太阳晒得发烫，鞋底踩上去软软的。路边有人在卖枇杷，黄澄澄堆在筐里，香气很浓。我多看了两眼，又收回视线。</p><p>“你还吃枇杷吗。”她忽然问。</p><p>“吃。”我说。</p><p>“那等明年熟了，我给你留。”她说得很自然，好像明年很近，又好像很远。</p><p>我点点头，手指悄悄握紧了袋子里的那张纸条。纸边硌着掌心，有点疼。</p><p>走到岔路口，她停下来，从口袋里掏出一个小东西，塞进我手里。</p><p>是一颗纸星星，叠得很紧，角尖尖的。</p><p>“这个给你。”她说，“路上看。”</p><p>我握着星星，纸面粗糙，带着她手心的温度。</p><p>“谢谢。”我说。</p><p>她笑了一下，铃铛随着她的动作轻轻晃，发出最后一下清响。</p><p>“到了新学校，记得写纸条。”她说，“你写的字好看。”</p><p>“好。”我说，“你也要好好的。”</p><p>她挥挥手，转身走了。她的背影越来越小，铃铛声越来越轻，最后被风吹散，听不见了。</p><p>我站在原地，看着她的影子拐过墙角，看不见了，才慢慢往回走。</p><p>晚上收拾行李，我把那颗新的纸星星和旧的放在一起，又把枇杷纸条压在最上面。箱子合上时，拉链声很顺，一下就拉到底了。屋里安静下来，能听见自己的呼吸。</p><p>窗外月亮升起来，白白的一块。风里有桂花的香，还有远处人家做饭的烟火气。我躺在床上，摸着袋子里的纸和星星，心里空了一块，又被什么填满，沉沉的。</p><p>我想，去了市三中，课程不同，时间不同，见面的机会大概很少了。南雾中学的铃铛声，旧教室的风，以后都只能留在记忆里。</p><p>我以为，我们不会再见了。</p>',69)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
